<script>
	// Generated by ../asciiArt from the source photographs there.
	import AsciiClock from '$lib/components/AsciiClock.svelte';
	import AsciiShip from '$lib/components/AsciiShip.svelte';
	import Capacity from '$lib/components/Capacity.svelte';
	import Dashboard from '$lib/components/Dashboard.svelte';
	import Dial from '$lib/components/Dial.svelte';
	import Heatmap from '$lib/components/Heatmap.svelte';
	import Horizon from '$lib/components/Horizon.svelte';
	import Panel from '$lib/components/Panel.svelte';
	import Placeholder from '$lib/components/Placeholder.svelte';
	import Spread from '$lib/components/Spread.svelte';
	import Stack from '$lib/components/Stack.svelte';
	import TimeAxis from '$lib/components/TimeAxis.svelte';
	import Trace from '$lib/components/Trace.svelte';
	import {
		clockPosition,
		degrees,
		microseconds,
		microspan,
		pct,
		ppm,
		rate,
		stamp
	} from '$lib/format.js';
	import { fleet } from '$lib/containers.js';
	import { memoryBands } from '$lib/memory.js';
	import { server, watch } from '$lib/server.svelte.js';
	import { bucket, last, mean, outages, percentile, summarise } from '$lib/stats.js';
	import { volume } from '$lib/storage.js';
	import { spread } from '$lib/time.js';

	/* Wireframe. CPU and storage are wired up; everything else is a placeholder
	   holding the shape of what goes there. One entry per section of the page and
	   per stop on the rail: a section is a box on the page, its own heading, and
	   its own place in the list. */
	const SECTIONS = [
		{ id: 'overview', label: 'Overview', hideTitle: true },
		{ id: 'cpu', label: 'CPU', hideTitle: true },
		{ id: 'memory', label: 'Memory', hideTitle: true },
		{ id: 'storage', label: 'Storage', hideTitle: true },
		{ id: 'network', label: 'Network', hideTitle: true },
		{ id: 'time', label: 'Time', hideTitle: true },
		{ id: 'containers', label: 'Containers', hideTitle: true }
	];

	/* The two drives. One entry each: the id is the prefix every one of their
	   series is named with, and the tone is theirs wherever they appear — capacity
	   box, horizon, io lane. */
	const DISKS = [
		{ id: 'nvme', label: 'NVMe', tone: 'var(--violet)' },
		{ id: 'ssd', label: 'SSD', tone: 'var(--azure)' }
	];

	/* Columns in the heatmaps. The series is 24h at five-minute steps, so this is
	   about a quarter-hour a cell — fine enough to see a spike, coarse enough that
	   a cell is still a cell rather than a hairline. */
	const HEAT_COLUMNS = 72;

	/* Bars in the rail's uptime strip: a much narrower box than the dashboard's
	   own heatmaps, so fewer of them read clean. */
	const UPTIME_BARS = 48;

	$effect(watch);

	let snapshot = $derived(server.snapshot);
	let series = $derived(server.series);
	let month = $derived(server.month);

	/* How the machine's memory is divided, as three shares of the whole. */
	let ram = $derived(memoryBands(series));

	/* One band's own current share, read off the same series the chart under it
	   draws — the headline number and the band it names are never worked out
	   two different ways. */
	const ramShare = (id) => last(ram.find((band) => band.id === id)?.points ?? []);

	/* Each volume worked out from its own 30-day series: where it is, which way it
	   is going, and when that runs out. The capacity boxes and the horizon are the
	   same objects seen two ways. */
	let volumes = $derived(
		DISKS.map((disk) =>
			volume({
				...disk,
				used: month?.[`${disk.id}UsedBytes`],
				available: month?.[`${disk.id}AvailableBytes`],
				percent: month?.[`${disk.id}Percent`]
			})
		)
	);

	/* The live reading, written the way $lib/format.js writes that quantity — the
	   same spelling the stats and the map key beside it use, so one number is not
	   quoted to two precisions in one box. */
	const reading = (key, format) => format(snapshot?.[key]);

	/* Read and write on each disk, a lane of that disk's own pulse map — the two
	   sit orders of magnitude apart on the same drive, so the map normalises per
	   row: a lane says when that stream was busy, not how it compares to the one
	   under it. Keyed by disk, since each now draws in its own column rather than
	   sharing one map between both drives. */
	let ioByDisk = $derived(
		Object.fromEntries(
			DISKS.map(({ id, tone }) => [
				id,
				['Read', 'Write']
					.map((direction) => {
						const points = series?.[`${id}${direction}BytesPerSecond`];
						return {
							id: direction,
							tone,
							now: rate(last(points)),
							cells: bucket(points, HEAT_COLUMNS)
						};
					})
					.filter((lane) => lane.cells.length)
			])
		)
	);

	/* Per-core utilisation as a map: one row a core, one cell a bucket, straight
	   off the same 0-100% scale the traces are drawn against. */
	let cores = $derived(
		Object.entries(series?.cpuPerCorePercent ?? {})
			.sort(([a], [b]) => Number(a) - Number(b))
			.map(([id, points]) => ({
				id: `C${id}`,
				now: pct(last(points)),
				cells: bucket(points, HEAT_COLUMNS)
			}))
	);

	/* Five figures over the window a series covers: the shape a reading took, not
	   just where it stands now. Every formatter already writes a non-finite
	   number as an em dash, so an empty series needs no guard of its own here --
	   min/max of nothing is +-Infinity, mean and percentile of nothing are NaN,
	   and all three print the same dash the rest of the page uses for "no
	   history yet". */
	const statsRow = (points, format) => {
		const values = (points ?? []).map((p) => p[1]);
		return [
			format(Math.min(...values)),
			format(percentile(values, 0.5)),
			format(mean(values)),
			format(percentile(values, 0.95)),
			format(Math.max(...values))
		];
	};

	let cpuStats = $derived([
		{ label: 'Usage (%)', tone: 'var(--mint)', row: statsRow(series?.cpuPercent, pct) },
		{ label: 'Pressure (%)', tone: 'var(--coral)', row: statsRow(series?.cpuPressurePercent, pct) },
		{
			label: 'Temperature (°C)',
			tone: 'var(--amber)',
			row: statsRow(series?.cpuTemperatureC, degrees)
		}
	]);

	/* The three bands History stacks, read the same way as any other share, plus
	   the two lines Pressure draws -- one row a series, same as CPU's table. */
	let memoryStats = $derived([
		{
			label: 'Used (%)',
			tone: 'var(--mint)',
			row: statsRow(ram.find((band) => band.id === 'used')?.points, pct)
		},
		{
			label: 'Cache (%)',
			tone: 'var(--violet)',
			row: statsRow(ram.find((band) => band.id === 'cache')?.points, pct)
		},
		{
			label: 'Free (%)',
			tone: 'var(--azure)',
			row: statsRow(ram.find((band) => band.id === 'free')?.points, pct)
		},
		{
			label: 'Pressure Some (%)',
			tone: 'var(--amber)',
			row: statsRow(series?.memoryPressureSomePercent, pct)
		},
		{
			label: 'Pressure Full (%)',
			tone: 'var(--coral)',
			row: statsRow(series?.memoryPressureFullPercent, pct)
		}
	]);

	/* One table a drive, the same split the temperature trace and the io pulse
	   beside it already draw: how full it ran, how hot, and its two lanes. */
	let storageStats = $derived(
		Object.fromEntries(
			volumes.map((vol) => [
				vol.id,
				[
					{ label: 'Used (%)', tone: vol.tone, row: statsRow(series?.[`${vol.id}Percent`], pct) },
					{
						label: 'Temperature (°C)',
						tone: vol.tone,
						row: statsRow(series?.[`${vol.id}TemperatureC`], degrees)
					},
					{
						label: 'Read',
						tone: vol.tone,
						row: statsRow(series?.[`${vol.id}ReadBytesPerSecond`], rate)
					},
					{
						label: 'Write',
						tone: vol.tone,
						row: statsRow(series?.[`${vol.id}WriteBytesPerSecond`], rate)
					}
				]
			])
		)
	);

	/* The two lines Throughput draws, plus the probe latency beside it -- rx and
	   tx keep the same tones they draw in up there. */
	let networkStats = $derived([
		{ label: 'RX', tone: 'var(--azure)', row: statsRow(rx, rate) },
		{ label: 'TX', tone: 'var(--violet)', row: statsRow(tx, rate) },
		{ label: 'Latency', tone: 'var(--azure)', row: statsRow(series?.latencyMs, ms) }
	]);

	/* Just the one line Offset History draws: Source Offsets beside it is a
	   snapshot of each source's own register, not a series, so it has no window
	   to summarise. */
	let timeStats = $derived([
		{ label: 'Offset', tone: 'var(--azure)', row: statsRow(clockHistory, microseconds) }
	]);

	let rx = $derived(series?.networkReceiveBytesPerSecond ?? []);
	let tx = $derived(series?.networkTransmitBytesPerSecond ?? []);
	const ms = (v) => (Number.isFinite(v) ? `${Math.round(v)} ms` : '—');

	/* Both directions to a count, the way the errors beside them read: a packet
	   lost on the way out is the same fault as one lost on the way in, and which
	   end it happened at is not something this reading can act on. */
	let networkDrops = $derived(
		snapshot ? snapshot.networkReceiveDropsPerSecond + snapshot.networkTransmitDropsPerSecond : null
	);
	let networkErrors = $derived(
		snapshot ? snapshot.networkReceiveErrorsPerSecond + snapshot.networkTransmitErrorsPerSecond : null
	);
	/* Rounded: these are counts a second, and summing two of them is what turns
	   0.1 and 0.2 into 0.30000000000000004. */
	const perSecond = (v) => (Number.isFinite(v) ? `${+v.toFixed(2)}/s` : '—');

	/* The clock, and every source it listens to as a reading with a bound. */
	let clock = $derived(snapshot?.time);
	let offsets = $derived(spread(clock));

	/* Chrony reports the correction needed to reach NTP: a negative correction
	   means this machine is fast. Flip it here so positive reads naturally as
	   PHOBOS ahead and negative as PHOBOS behind. */
	let clockHistory = $derived(
		(series?.timeSystemOffsetSeconds ?? []).map(([time, offset]) => [time, -offset])
	);
	let currentClockOffset = $derived(
		Number.isFinite(clock?.systemOffsetSeconds) ? -clock.systemOffsetSeconds : null
	);
	let clockLimit = $derived.by(() => {
		const greatest = Math.max(50e-6, ...clockHistory.map((point) => Math.abs(point[1])));
		return Math.ceil((greatest * 1.15) / 50e-6) * 50e-6;
	});
	/* The containers as the fleet and its slots, both already written out. */
	let containerFleet = $derived(fleet(snapshot?.containers));

	let online = $derived(snapshot?.server === 'online');

	/* The status series is 1 for a poll the machine answered and 0 for one it did
	   not: bucketed into bars for the rail's strip, and counted outright for the
	   incident line above it. */
	let uptime = $derived(series?.status ?? []);
	let incidents = $derived(outages(uptime));
	let uptimeBars = $derived(
		bucket(uptime, UPTIME_BARS).map((v) => (v === null ? 'unknown' : v < 1 ? 'down' : 'up'))
	);

	/* CPU, memory and each drive on its own: a share, and which section states
	   it in full. Storage is the two volumes rather than one reading picked
	   between them, so a dial standing for a drive stands for one drive. */
	let overviewMetrics = $derived([
		{ label: 'CPU usage', percent: snapshot?.cpuPercent, tone: 'var(--mint)' },
		{ label: 'Memory', percent: snapshot?.memoryPercent, tone: 'var(--violet)' },
		...volumes.map((vol) => ({
			label: vol.label,
			percent: vol.percentNow ?? snapshot?.[`${vol.id}Percent`],
			tone: vol.tone
		}))
	]);
</script>

<svelte:head>
	<title>Server — Joshua Smith</title>
</svelte:head>

<!-- One row a series, in that series' own tone: every section below renders
     this over its own rows rather than repeating the table markup. -->
{#snippet statsTable(rows, span = 'span-12')}
	<div class="box {span}">
		<Panel label="24H Statistics">
			<div class="fleet">
				<table>
					<thead>
						<tr>
							<th class="eyebrow" scope="col">Metric</th>
							{#each ['Min', 'Median', 'Avg', 'P95', 'Max'] as column (column)}
								<th class="eyebrow" scope="col">{column}</th>
							{/each}
						</tr>
					</thead>

					<tbody>
						{#each rows as { label, tone, row } (label)}
							<tr style:color={tone}>
								<th scope="row">{label}</th>
								{#each row as value, i (i)}<td>{value}</td>{/each}
							</tr>
						{/each}
					</tbody>
				</table>
			</div>
		</Panel>
	</div>
{/snippet}

{#snippet overview()}
	<!-- The same strip every other section opens with, a dial standing in for
	     the plain figure a headline reading usually is. -->
	<div class="box headline">
		<div class="lede">
			<p class="section-name">Overview</p>
		</div>

		{#each overviewMetrics as metric (metric.label)}
			<div class="stat dial-stat">
				<Dial label={metric.label} percent={metric.percent} tone={metric.tone} />
				<span class="eyebrow">{metric.label}</span>
			</div>
		{/each}
	</div>

	<div class="grid">
		<div class="box span-12"><Placeholder note="more overview panels" lines={16} /></div>
	</div>
{/snippet}

{#snippet cpu()}
	<!-- The section's own title and the headline readings in one box: the
	     section dropped its generic frame and heading (see Dashboard's
	     hide-title), so this names it instead. Model, frequency and power draw
	     are not wired up yet, so they stand as placeholders rather than numbers
	     this build does not have. -->
	<div class="box headline">
		<div class="lede">
			<p class="section-name">CPU</p>
		</div>

		<div class="stat">
			<strong class="figure">{reading('cpuPercent', pct)}</strong>
			<span class="eyebrow">Usage</span>
		</div>

		<div class="stat">
			<strong class="figure">{reading('cpuPressurePercent', pct)}</strong>
			<span class="eyebrow">Pressure</span>
		</div>

		<div class="stat" style:color="var(--amber)">
			<strong class="figure">{reading('cpuTemperatureC', degrees)}</strong>
			<span class="eyebrow">Temp</span>
		</div>

		<div class="stat">
			<Placeholder note="ghz" lines={1} />
			<span class="eyebrow">Freq</span>
		</div>

		<div class="stat">
			<Placeholder note="watts" lines={1} />
			<span class="eyebrow">Power</span>
		</div>
	</div>

	<!-- Usage over the window beside how it splits across cores: the one
	     trace and the one map that read the same reading two ways. -->
	<div class="grid">
		<div class="box span-4">
			<Panel label="CPU Usage (%)">
				<Trace
					lines={[{ id: 'usage', points: series?.cpuPercent, tone: 'var(--mint)' }]}
					domain={[0, 100]}
					format={pct}
				/>
			</Panel>
		</div>

		<div class="box span-8">
			<!-- The key spells out the band the colours cover, since the map is
			     stretched to the range the cores actually ran at. -->
			<Panel label="Per Core Usage">
				<Heatmap rows={cores} format={pct} note="no per-core history yet" />
			</Panel>
		</div>
	</div>

	<div class="grid">
		<div class="box span-6">
			<!-- Sustained pressure is the reading that matters rather than any one
			     spike, so the rules are the two levels worth seeing a trace cross. -->
			<Panel label="CPU Pressure (%)">
				<Trace
					lines={[{ id: 'pressure', points: series?.cpuPressurePercent, tone: 'var(--coral)' }]}
					domain={[0, 100]}
					format={pct}
					marks={[25, 50]}
				/>
			</Panel>
		</div>

		<div class="box span-6">
			<!-- Not zero-based like usage and pressure: nothing here runs near an
			     ambient 0°C, so the bottom 40° of the axis would be empty and the
			     trace flat against the top of it. -->
			<Panel label="CPU Temperature (°C)">
				<Trace
					lines={[{ id: 'temperature', points: series?.cpuTemperatureC, tone: 'var(--amber)' }]}
					domain={[40, 100]}
					format={degrees}
					marks={[60, 80]}
				/>
			</Panel>
		</div>
	</div>

	{@render statsTable(cpuStats)}

	<!-- Wireframe filler: holds the section at a full screen until the sensors
	     that would fill it (frequency history, per-core temperature, whatever
	     else the headline's own Freq/Power placeholders end up wired to) land. -->
	<div class="grid">
		<div class="box span-12"><Placeholder note="more cpu panels" lines={6} /></div>
	</div>
{/snippet}

{#snippet memory()}
	<div class="box headline">
		<div class="lede">
			<p class="section-name">Memory</p>
		</div>

		<div class="stat">
			<strong class="figure">{reading('memoryPercent', pct)}</strong>
			<span class="eyebrow">Usage</span>
		</div>

		<div class="stat" style:color="var(--violet)">
			<strong class="figure">{pct(ramShare('cache'))}</strong>
			<span class="eyebrow">Cache</span>
		</div>

		<div class="stat" style:color="var(--azure)">
			<strong class="figure">{pct(ramShare('free'))}</strong>
			<span class="eyebrow">Free</span>
		</div>
	</div>

	<div class="grid">
		<div class="box span-8">
			<!-- Used, cache and free, which is how the memory is actually divided: the
			     cache is the part the machine would give back under pressure. -->
			<Panel label="Memory History">
				<Stack bands={ram} note="no memory history yet" />
			</Panel>
		</div>

		<div class="box span-4">
			<!-- No domain: this reading lives in hundredths of a percent, so the scale
			     is the range it covered rather than the 0-100 a share could take. Some
			     is any task waiting on memory, full is every task waiting at once —
			     the second is the one that means the machine stopped. -->
			<Panel label="Memory Pressure (%)">
				<Trace
					lines={[
						{ id: 'some', points: series?.memoryPressureSomePercent, tone: 'var(--amber)', label: 'Some' },
						{ id: 'full', points: series?.memoryPressureFullPercent, tone: 'var(--coral)', label: 'Full', dashed: true }
					]}
					format={pct}
				/>
			</Panel>
		</div>
	</div>

	{@render statsTable(memoryStats)}

	<div class="grid">
		<div class="box span-12"><Placeholder note="more memory panels" lines={6} /></div>
	</div>
{/snippet}

{#snippet storage()}
	<div class="box headline">
		<div class="lede">
			<p class="section-name">Storage</p>
		</div>

		{#each volumes as vol (vol.id)}
			<!-- The series' last percent, or the live snapshot's until the history
			     has one: the reading is the same either way. -->
			<div class="stat dial-stat">
				<Dial label={vol.label} percent={vol.percentNow ?? snapshot?.[`${vol.id}Percent`]} tone={vol.tone} />
				<span class="eyebrow">{vol.label}</span>
			</div>
		{/each}
	</div>

	<!-- One column a disk, so NVMe and SSD line up across the four rows below
	     rather than each running its own four deep — the same reading on the
	     two is what is worth reading across, not down. -->
	<div class="grid">
		{#each volumes as vol (vol.id)}
			<div class="box span-6">
				<Panel label="{vol.label} Capacity">
					<Capacity
						label={vol.label}
						percent={vol.percentNow ?? snapshot?.[`${vol.id}Percent`]}
						tone={vol.tone}
					/>
				</Panel>
			</div>
		{/each}
	</div>

	<div class="grid">
		{#each volumes as vol (vol.id)}
			<div class="box horizon-box span-6">
				<!-- Bounded to this disk's own floor and year-out projection rather
				     than a fixed 0-100%, so the two columns read their own slope
				     instead of each fighting the whole drive for room. -->
				<Horizon volume={vol} label="{vol.label} Used Space History &amp; Projection" />
			</div>
		{/each}
	</div>

	<div class="grid">
		{#each volumes as vol (vol.id)}
			<div class="box span-6">
				<!-- Same fixed floor as the CPU's temperature trace: nothing here
				     runs near ambient either. -->
				<Panel label="{vol.label} Temperature (°C)">
					<Trace
						lines={[{ id: 'temperature', points: series?.[`${vol.id}TemperatureC`], tone: vol.tone }]}
						domain={[20, 90]}
						format={degrees}
						marks={[50, 70]}
					/>
				</Panel>
			</div>
		{/each}
	</div>

	<div class="grid">
		{#each volumes as vol (vol.id)}
			<div class="box io span-6">
				<Panel label="{vol.label} I/O Pulse">
					<!-- Read and write, stretched to this disk's own busiest quarter-hour,
					     so the key quotes that lane's own floor and ceiling in bytes a
					     second. -->
					<Heatmap rows={ioByDisk[vol.id]} normalise="row" format={rate} note="no io history yet" />
				</Panel>
			</div>
		{/each}
	</div>

	<!-- One table a drive, same as the three grids above. -->
	<div class="grid">
		{#each volumes as vol (vol.id)}
			{@render statsTable(storageStats[vol.id], 'span-6')}
		{/each}
	</div>
{/snippet}

{#snippet network()}
	<div class="box headline">
		<div class="lede">
			<p class="section-name">Network</p>
		</div>

		<div class="stat" style:color="var(--azure)">
			<strong class="figure">{pct(snapshot?.networkUtilizationPercent)}</strong>
			<span class="eyebrow">Utilisation</span>
		</div>

		<div class="stat">
			<strong class="figure">{reading('latencyMs', ms)}</strong>
			<span class="eyebrow">Latency</span>
		</div>

		<div class="stat">
			<strong class="figure">{perSecond(networkDrops)}</strong>
			<span class="eyebrow">Drops</span>
		</div>

		<div class="stat">
			<strong class="figure">{perSecond(networkErrors)}</strong>
			<span class="eyebrow">Errors</span>
		</div>

		<div class="stat">
			<strong class="figure">{perSecond(snapshot?.networkTcpRetransmitsPerSecond)}</strong>
			<span class="eyebrow">Retransmits</span>
		</div>
	</div>

	<div class="grid">
		<div class="box span-8">
			<Panel label="Throughput">
				<Trace
					lines={[
						{ id: 'rx', points: rx, tone: 'var(--azure)', label: 'RX' },
						{ id: 'tx', points: tx, tone: 'var(--violet)', label: 'TX' }
					]}
					format={rate}
				/>
			</Panel>
		</div>

		<div class="box span-4">
			<Panel label="HTTP Probe Latency">
				<p class="latency-reading">
					<strong>{reading('latencyMs', ms)}</strong><span>P95 {summarise(series?.latencyMs, ms)[2][1]}</span>
				</p>
				<Trace lines={[{ id: 'latency', points: series?.latencyMs, tone: 'var(--azure)' }]} format={ms} />
			</Panel>
		</div>
	</div>

	{@render statsTable(networkStats)}

	<div class="grid">
		<div class="box span-12"><Placeholder note="more network panels" lines={6} /></div>
	</div>
{/snippet}

{#snippet time()}
	<div class="box headline">
		<div class="lede">
			<p class="section-name">Time</p>
		</div>

		<div class="stat" style:color={clock?.synchronized && !clock?.stale ? undefined : 'var(--coral)'}>
			<strong class="figure">
				{clock?.synchronized ? clockPosition(currentClockOffset) : 'Not synchronised'}
			</strong>
			<span class="eyebrow">{clock?.stale ? 'Offset (stale)' : 'Offset'}</span>
		</div>

		{#each [
			['RMS offset', microspan(clock?.rmsOffsetSeconds)],
			['Root delay', microspan(clock?.rootDelaySeconds)],
			['Root dispersion', microspan(clock?.rootDispersionSeconds)],
			['Frequency', ppm(clock?.frequencyPpm)],
			['Stratum', clock?.stratum ?? '—'],
			['Leap status', clock?.leapStatus ?? '—']
		] as [label, value] (label)}
			<div class="stat">
				<strong class="figure">{value}</strong>
				<span class="eyebrow">{label}</span>
			</div>
		{/each}
	</div>

	<div class="grid">
		<div class="box span-8">
			<!-- The bar is what each source admits it could be wrong by, so a short
			     one is a source worth following. They agree on the offset to a
			     fraction of a millisecond and differ sevenfold on their confidence,
			     which is the whole reading. -->
			<Panel label="Source Offsets">
				<Spread rows={offsets} format={microseconds} note="no time sources reported" />
			</Panel>
		</div>

		<div class="box span-4">
			<!-- Decorative: the figures beside it above already say what time it is,
			     down to the microsecond this section is all about. -->
			<Panel label="UTC">
				<div class="clock-box" aria-hidden="true"><AsciiClock /></div>
			</Panel>
		</div>
	</div>

	<div class="box history">
		<Panel label="Offset History">
			<Trace
				lines={[{ id: 'offset', points: clockHistory, tone: 'var(--azure)', area: false }]}
				domain={[-clockLimit, clockLimit]}
				marks={[0]}
				format={microseconds}
			/>
		</Panel>
	</div>

	{@render statsTable(timeStats)}

	<div class="grid">
		<div class="box span-12"><Placeholder note="more time panels" lines={6} /></div>
	</div>
{/snippet}

{#snippet containers()}
	<div class="box headline">
		<div class="lede">
			<p class="section-name">Containers</p>
		</div>

		<div class="stat">
			<strong class="figure">{containerFleet.running}</strong>
			<span class="eyebrow">Running</span>
		</div>

		<div class="stat" style:color={containerFleet.unhealthy > 0 ? 'var(--coral)' : undefined}>
			<strong class="figure">{containerFleet.unhealthy}</strong>
			<span class="eyebrow">Unhealthy</span>
		</div>

		<div class="stat">
			<strong class="figure">{containerFleet.memory}</strong>
			<span class="eyebrow">In use</span>
		</div>
	</div>

	<!-- Decorative: the section is named by its heading, and the art is thousands
	     of digits to a screen reader. -->
	<div class="box ship-box" aria-hidden="true">
		<div class="art ship"><AsciiShip /></div>
	</div>

	{#if containerFleet.slots.length}
		<div class="box">
			<div class="container-shell">
				<!-- One row a container, one column a reading: the names of the readings
				     are the header, so no row has to repeat them. Scrolls sideways rather
				     than reflowing, because a row read across is the whole point of it. -->
				<div class="fleet">
					<table>
						<thead>
							<tr>
								{#each ['Container', 'Status', 'CPU', 'CPU limit', 'Memory', 'Memory limit', 'Uptime'] as column (column)}
									<th class="eyebrow" scope="col">{column}</th>
								{/each}
							</tr>
						</thead>

						<tbody>
							{#each containerFleet.slots as slot (slot.name)}
								<tr>
									<!-- The name docker knows it by, set as the literal it is. -->
									<th class="name" scope="row">{slot.name}</th>
									<td class="state" class:warning={!slot.healthy}>
										<i aria-hidden="true"></i>{slot.status}
									</td>

									<!-- What it is using of what it was given, in that resource's own
									     colour: the reading with the share it comes to under it, then
									     the allowance that share is measured against. -->
									{#each slot.resources as resource (resource.id)}
										<td class="usage" style:color={resource.tone}>
											{resource.value}
											<i class="resource-bar"><i style:width="{resource.fill}%"></i></i>
										</td>
										<td class="limit">{resource.limit}</td>
									{/each}

									<td>{slot.uptime}</td>
								</tr>
							{/each}
						</tbody>
					</table>
				</div>
			</div>
		</div>
	{:else}
		<Placeholder note="no container data" lines={3} />
	{/if}

	<div class="grid">
		<div class="box span-12"><Placeholder note="more container panels" lines={6} /></div>
	</div>
{/snippet}

<Dashboard title="Server" sections={SECTIONS} max="88rem">
	<!-- Each section's body is the snippet named after it. -->
	{#snippet body(section)}
		{@render { overview, cpu, memory, storage, network, time, containers }[section.id]()}
	{/snippet}

	{#snippet rail()}
		<div class="rail-box status">
			<h2 class="eyebrow">Status</h2>
			<p class="figure verdict"><i class="dot" aria-hidden="true"></i>Healthy</p>
			<p class="note">Nothing to report</p>
		</div>

		<div class="rail-box uptime">
			<h2 class="eyebrow">Uptime</h2>
			<p class="figure">
				{online ? Math.floor(snapshot.uptimeSeconds / 3600) : '—'}<span class="unit">h</span>
			</p>
			<p class="stats">
				{uptime.length
					? incidents
						? `${incidents} incident${incidents > 1 ? 's' : ''}`
						: 'No incidents'
					: 'No history yet'}
			</p>
			<div class="strip" role="img" aria-label="Server uptime over the last 24 hours">
				{#each uptimeBars as state}<i class={state}></i>{/each}
			</div>
			<TimeAxis />
		</div>
	{/snippet}

	{#snippet foot()}
		<span class="eyebrow">Last updated</span>
		<!-- The stamp the snapshot came with, not the clock: this says how fresh
		     the numbers above are, which is not the same as what time it is. -->
		<span class="mono">{stamp(snapshot?.generatedAt)}</span>
	{/snippet}
</Dashboard>

<style>
	.mono {
		color: var(--text-dim);
		font-family: var(--font-mono);
		font-size: 0.72rem;
	}

	/* A piece of generated ascii art. A character grid has one size — how big one
	   cell is — so the art is sized by setting that from the box it sits in, and
	   --cols is how many cells wide the grid measures: its column count times the
	   0.6021em JetBrains Mono advances per character. Every piece on this page
	   therefore spans its box and shrinks with it. */
	.art {
		container-type: inline-size;
	}

	.art :global(pre) {
		font-size: calc(100cqw / var(--cols));
		/* The generator sets line-height 0.72, which at these sizes lands between
		   pixels (9.55 x 0.72 = 6.88). Painting rounds each row's baseline on its
		   own, so a fractional pitch comes out as a 7, 7, 7, 6 rhythm: every fourth
		   row sits a pixel tight against the one above and the collisions read as
		   horizontal bands across the picture. Rounding the pitch to something a row
		   can be painted at makes every row the same height instead.

		   This is a ratio of the font size, not a fixed height, so it tracks the art
		   as it scales with its container. What it costs is the rounding: the rows
		   are up to half a device pixel off the 0.72, which is under 3% of the
		   picture's height wherever a digit in it is legible. */
		line-height: round(0.72em, var(--device-px, 1px));
	}

	/* 166 columns, which at the width of a section box is the ~9.5px the bull's own
	   digits are set at on a laptop screen. This is the cell size, not a count of
	   what is in any one picture: every piece that heads a section is scaled by it,
	   so a digit is one size across the page whether that art turns out to be 164
	   columns or 166. */
	.ship {
		--cols: 99.95;
		/* A grid of stubs follows it; the foot under the dish brings its own air. */
		margin-bottom: 0.75rem;
	}

	/* The section's own name on the left, the headline readings spread across
	   the rest. Flex rather than a grid of a fixed count of columns: every
	   section carries a different number of these, and flex-wrap wraps a run
	   that outgrows the width instead of squeezing every column of every
	   section to whatever the busiest one needs. */
	.headline {
		display: flex;
		flex-wrap: wrap;
		align-items: center;
		gap: 1rem clamp(1.5rem, 3vw, 2.5rem);
	}

	/* Tighter top and bottom than a box normally wears, so a dial standing in
	   this strip comes close to the edges instead of floating in the middle of
	   a gap sized for a line of text. Left and right keep the usual --pad, so
	   the box still lines up with the ones below it. The extra specificity
	   (over .box's own) is what makes this win regardless of source order. */
	.box.headline {
		padding-block: 0.5rem;
	}

	.lede {
		display: flex;
		flex-direction: column;
		gap: 0.35rem;
		/* Pushes every .stat after it to the row's far edge, wrapping together
		   as one run rather than trailing the name across the box. */
		margin-right: auto;
	}

	/* The name every other section wears as its own hidden h2, worn here as
	   plain text instead: this box is what makes it a heading, not the tag. */
	.lede .section-name {
		margin: 0;
		color: var(--color-foreground);
		font-size: 1.4rem;
		font-weight: 700;
		letter-spacing: -0.01em;
	}

	/* Value above label, the opposite order a .readout reads in: this is the
	   one figure a glance wants, not a name to look a number up by. */
	.stat {
		display: flex;
		flex-direction: column;
		gap: 0.3rem;
		min-width: 5rem;
	}

	.stat .figure {
		font-size: 1.3rem;
	}

	/* The overview's dials are the one .stat whose reading isn't a flush-left
	   line of text — centred over its own label instead, the way a gauge reads
	   rather than the way a figure does. */
	.dial-stat {
		align-items: center;
	}

	/* The two readings stood above the rail's nav: the same box vocabulary as
	   the overview's dials, sized for the rail's own width rather than the
	   page's. */
	.rail-box {
		padding: 0.9rem 1rem;
		border: 1px solid var(--color-border);
		border-radius: 0.4rem;
		background: var(--surface);
	}

	.rail-box .eyebrow {
		display: block;
		margin-bottom: 0.5rem;
	}

	.rail-box .figure {
		margin: 0;
		font-size: 1.4rem;
	}

	.status .verdict {
		display: flex;
		align-items: center;
		gap: 0.5rem;
		color: var(--mint);
	}

	/* The same lit dot the rail marks the section you are in with. */
	.status .dot {
		width: 0.55rem;
		height: 0.55rem;
		border-radius: 50%;
		background: currentcolor;
		box-shadow: 0 0 0.6em currentcolor;
	}

	.status .note {
		margin: 0.35rem 0 0;
		color: var(--text-dim);
		font-size: 0.72rem;
	}

	.uptime .unit {
		margin-left: 0.15em;
		color: var(--text-dim);
		font-size: 0.6em;
		font-weight: 500;
	}

	.uptime .stats {
		margin: 0.3rem 0 0.7rem;
		color: var(--text-dim);
		font-size: 0.6rem;
		font-weight: 500;
		letter-spacing: 0.08em;
		text-transform: uppercase;
	}

	/* One bar a bucket, the same vocabulary the dashboard's own heatmaps draw
	   cells with: mint where the machine answered, coral where it did not. */
	.strip {
		display: grid;
		grid-auto-flow: column;
		grid-auto-columns: 1fr;
		gap: 1px;
		height: 1.6rem;
		margin-bottom: 0.5rem;
	}

	.strip i {
		border-radius: 1px;
		/* The bare bar is unknown, not down: dim enough to read as "no data"
		   beside the mint, and never mistakable for an outage. */
		background: color-mix(in srgb, var(--mint) 12%, var(--color-background));
	}

	.strip i.up {
		background: var(--mint);
	}

	.strip i.down {
		background: var(--coral);
	}

	/* Bleeds the table out to the edges of the box that holds it, cancelling
	   that box's own padding on three sides — .fleet's overflow-x is what
	   actually keeps the table's width from pushing the box (or the section
	   around it) wider than its column, so nothing here has to. */
	.container-shell {
		margin-inline: calc(-1 * var(--pad));
		margin-bottom: calc(-1 * var(--pad));
	}

	/* A row is read across, so it is never broken up to fit: under the width the
	   columns need, the table keeps its shape and the box scrolls. */
	.fleet {
		overflow-x: auto;
		scrollbar-width: thin;
	}

	.fleet table {
		width: 100%;
		border-collapse: collapse;
		font-family: var(--font-mono);
		font-size: 0.68rem;
	}

	/* Left, like everything else on the page, and never wrapped: a reading broken
	   over two lines stops being one. The gutter is on the right of every cell, and
	   the section's own padding on the two outside ones, so the rules still run wall
	   to wall. */
	.fleet th,
	.fleet td {
		padding: 0.65rem 1.5rem 0.65rem 0;
		font-weight: 400;
		text-align: left;
		white-space: nowrap;
	}

	.fleet tr > :first-child {
		padding-left: var(--pad);
	}

	.fleet tr > :last-child {
		padding-right: var(--pad);
	}

	/* The header names the columns once. It is the one row set in the page's small
	   caps rather than mono: it is a label, not a reading. */
	.fleet thead th {
		padding-top: var(--divide);
		padding-bottom: 0.5rem;
		border-bottom: var(--rule);
	}

	.fleet tbody tr + tr th,
	.fleet tbody tr + tr td {
		border-top: var(--rule);
	}

	.name {
		color: var(--color-foreground);
	}

	/* A square of the state's own colour, and the word beside it — the colour is
	   never the only thing saying which way a row reads. */
	.state {
		color: var(--mint);
		text-transform: capitalize;
	}

	.state i {
		display: inline-block;
		width: 0.45rem;
		height: 0.45rem;
		margin-right: 0.5rem;
		background: currentcolor;
	}

	/* The allowance the reading beside it is drawn against, set back from it: the
	   number that moves is the one worth reading down the column. */
	.limit {
		color: var(--text-dim);
	}

	/* Wide enough that the share under the reading is a bar rather than a mark. */
	.usage {
		min-width: 5rem;
	}

	/* Under the reading, the width of the cell it is in. */
	.resource-bar {
		display: block;
		height: 2px;
		margin-top: 0.4rem;
		background: var(--color-border);
	}

	.resource-bar i {
		display: block;
		height: 100%;
		min-width: 0;
		background: currentcolor;
	}

	td.state.warning {
		color: var(--coral);
	}

	/* Every reading that sits in a band, at one size: these are rows of figures
	   read across and compared down the page, so a cell does not get to pick a
	   size of its own. Mono, unlike the .figure a whole section is known by —
	   this is a count, not a headline. */
	.latency-reading strong {
		font-family: var(--font-mono);
		font-size: 1.45rem;
		color: var(--violet);
	}

	/* Wall to wall along the foot of the section: a trace this wide is read across,
	   and the height only has to be enough to see the line move. */
	.history {
		--graph-min: 14.15rem;
	}

	/* The io map wants a wider gutter than the graphs above it: these row labels
	   are words ("Read", "Write"), not core numbers. */
	.io {
		--axis-w: 5rem;
	}

	/* The horizon chart fills its own box (100% of it) rather than sizing itself,
	   so that box needs a real height to fill — an auto one resolves its 100% to
	   nothing. */
	.horizon-box {
		height: 20rem;
	}

	/* Black rather than the surface every other box wears: the art is a picture
	   rather than a chart, and reads as one set against the same black the
	   overview's title stands on, not the page's own near-black surface. */
	.ship-box {
		background: #000;
	}

	/* Centred vertically in its panel rather than pinned to the top, the way
	   Spread's rows fill theirs beside it -- but full width, not centred on
	   that axis too: AsciiClock sizes its own digits off this box's width, so
	   shrinking it to its content would leave the width it measures against
	   circular. */
	.clock-box {
		display: grid;
		flex: 1;
		align-items: center;
		min-height: 7rem;
	}

	/* The unit belongs to the number, so it sits on its baseline rather than under
	   it. */
	.latency-reading {
		display: flex;
		align-items: baseline;
		gap: 1.25rem;
		margin: 0;
	}

	.latency-reading span {
		color: var(--text-faint);
		font-family: var(--font-mono);
		font-size: 0.6rem;
	}
</style>
